// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { typedndarray } from '@stdlib/types/ndarray';

/**
* Returns a fill value.
*
* @returns fill value
*/
type Nullary<ThisArg> = ( this: ThisArg ) => any;

/**
* Returns a fill value.
*
* @param value - current array element
* @returns fill value
*/
type Unary<T, ThisArg> = ( this: ThisArg, value: T ) => any;

/**
* Returns a fill value.
*
* @param value - current array element
* @param index - current array element index
* @returns fill value
*/
type Binary<T, ThisArg> = ( this: ThisArg, value: T, index: number ) => any;

/**
* Returns a fill value.
*
* @param value - current array element
* @param index - current array element index
* @param array - input ndarray
* @returns fill value
*/
type Ternary<T, U, ThisArg> = ( this: ThisArg, value: T, index: number, array: U ) => any;

/**
* Returns a fill value.
*
* @param value - current array element
* @param index - current array element index
* @param array - input ndarray
* @returns fill value
*/
type Callback<T, U, ThisArg> = Nullary<ThisArg> | Unary<T, ThisArg> | Binary<T, ThisArg> | Ternary<T, U, ThisArg>;

/**
* Fills a one-dimensional ndarray according to a provided callback function.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a zero-dimensional ndarray containing the starting index (inclusive).
*     -   a zero-dimensional ndarray containing the ending index (exclusive).
*
* @param arrays - array-like object containing ndarrays
* @param clbk - callback function
* @param thisArg - callback execution context
* @returns input ndarray
*
* @example
* var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
* var vector = require( '@stdlib/ndarray/vector/ctor' );
*
* function fill() {
*     return 5.0;
* }
*
* var x = vector( [ -2.0, 1.0, 3.0, -5.0, 4.0, -6.0 ], 'generic' );
*
* var start = scalar2ndarray( 0, {
*     'dtype': 'generic'
* });
*
* var end = scalar2ndarray( 3, {
*     'dtype': 'generic'
* });
*
* var out = gfillBy( [ x, start, end ], fill );
* // returns <ndarray>[ 5.0, 5.0, 5.0, -5.0, 4.0, -6.0 ]
*/
declare function gfillBy<T = unknown, V extends typedndarray<T> = typedndarray<T>, ThisArg = unknown>( arrays: [ V, typedndarray<number>, typedndarray<number> ], clbk: Callback<T, V, ThisArg>, thisArg?: ThisParameterType<Callback<T, V, ThisArg>> ): V;


// EXPORTS //

export = gfillBy;
